/bin/bash -lc 'tmpdir="${TMPDIR:-/var/folders}"; outfile="$tmpdir/crt_jabalpur.json"; curl --fail --location --show-error --silent --max-time 30 "https://crt.sh/?q=%25jabalpur%25&output=json" -o "$outfile"; rc=$?; echo "normal_rc=$rc"; if [ "$rc" -eq 60 ]; then curl --insecure --fail --location --show-error --silent --max-time 30 "https://crt.sh/?q=%25jabalpur%25&output=json" -o "$outfile"; rc=$?; echo "insecure_rc=$rc"; fi; if [ "$rc" -eq 0 ]; then wc -c "$outfile"; python3 - "$outfile" <<'"'PY'
import json,sys
try:j=json.load(open(sys.argv[1]))
except Exception as e: print(e); raise SystemExit
names=set()
for x in j:
 for n in x.get('name_value','').splitlines(): names.add(n.strip().lower())
for n in sorted(names): print(n)
PY
fi"

